package io.phext.libphext

import org.junit.jupiter.api.Assertions.assertArrayEquals
import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assertions.assertNotNull
import org.junit.jupiter.api.Assertions.assertNull
import org.junit.jupiter.api.Assertions.assertTrue
import org.junit.jupiter.api.Test
import java.io.File
import java.security.MessageDigest

/**
 * The shared libphext 0.6.1 range conformance fixtures (see
 * FIXTURES-RANGES.md in the fixture set): all 6 cases / 69 ops from
 * tests/fixtures/ranges, generated by libphext-rs 0.6.1. Every op in
 * each case's expected.tsv is consumed exactly as the format spec
 * defines: parse_point / parse_range compare the canonical serialization
 * (or the parse error), resolve_point compares the
 * "<universe>|<coordinate>|<char offset>" digest (or the resolution
 * error), and fetch_point / fetch_range compare result bytes against
 * results/NN.txt plus the `resolved` flag — whether resolution succeeds
 * must stay distinguishable from a resolved-but-empty fetch.
 */
class RangeFixturesTest {

    private val fixturesDir: File = File("tests/fixtures/ranges")

    private fun sha256(bytes: ByteArray): String {
        val digest = MessageDigest.getInstance("SHA-256").digest(bytes)
        return digest.joinToString("") { "%02x".format(it) }
    }

    @Test
    fun allRangeFixtureCases() {
        assertTrue(fixturesDir.isDirectory, "fixtures dir missing: ${fixturesDir.absolutePath}")
        val casesTsv = File(fixturesDir, "cases.tsv").readText(Charsets.UTF_8)
        val caseNames = casesTsv.lines()
            .filter { it.isNotBlank() }
            .drop(1) // header
            .map { it.split('\t')[0] }
        assertEquals(6, caseNames.size, "expected 6 range fixture cases")

        var totalOps = 0
        for (caseName in caseNames) {
            val caseDir = File(fixturesDir, caseName)
            val tsvLines = File(caseDir, "expected.tsv").readText(Charsets.UTF_8)
                .lines()
                .filter { it.isNotEmpty() }
            val header = HashMap<String, String>()
            val opLines = ArrayList<String>()
            for (line in tsvLines) {
                if (line.startsWith("op\t")) {
                    opLines.add(line)
                } else {
                    val tab = line.indexOf('\t')
                    header[line.substring(0, tab)] = line.substring(tab + 1)
                }
            }
            assertEquals(caseName, header["case"], "$caseName header case name")

            val inputBytes = File(caseDir, "input.phext").readBytes()
            assertEquals(header["input_bytes"]!!.toInt(), inputBytes.size, "$caseName input size")
            assertEquals(header["input_sha256"], sha256(inputBytes), "$caseName input sha256")

            // ops apply to chain 0 of parseChains(input)
            val chain = parseChains(inputBytes.toString(Charsets.UTF_8))[0]

            var caseOps = 0
            for (line in opLines) {
                val fields = line.split('\t')
                assertEquals("op", fields[0], "$caseName op line tag")
                val kind = fields[1]
                val input = fields[2]
                val kv = HashMap<String, String>()
                for (field in fields.drop(3)) {
                    val eq = field.indexOf('=')
                    kv[field.substring(0, eq)] = field.substring(eq + 1)
                }
                when (kind) {
                    "parse_point" -> {
                        val parsed = parsePointAddress(input)
                        if (kv["error"] == "true") {
                            assertNull(parsed, "$caseName parse_point ($input) must fail")
                        } else {
                            assertNotNull(parsed, "$caseName parse_point ($input) must parse")
                            assertEquals(kv["canonical"], parsed.toString(), "$caseName parse_point ($input)")
                        }
                    }
                    "parse_range" -> {
                        val parsed = parseRangeAddress(input)
                        if (kv["error"] == "true") {
                            assertNull(parsed, "$caseName parse_range ($input) must fail")
                        } else {
                            assertNotNull(parsed, "$caseName parse_range ($input) must parse")
                            assertEquals(kv["canonical"], parsed.toString(), "$caseName parse_range ($input)")
                        }
                    }
                    "resolve_point" -> {
                        val parsed = parsePointAddress(input)
                        assertNotNull(parsed, "$caseName resolve_point ($input) input must parse")
                        val resolved = chain.resolvePoint(parsed!!)
                        if (kv["error"] == "true") {
                            assertNull(resolved, "$caseName resolve_point ($input) must fail")
                        } else {
                            assertNotNull(resolved, "$caseName resolve_point ($input) must resolve")
                            assertEquals(
                                kv["resolve"],
                                "${resolved!!.first}|${resolved.second}|${resolved.third}",
                                "$caseName resolve_point ($input)",
                            )
                        }
                    }
                    "fetch_point" -> {
                        val expectedBytes = File(caseDir, kv["file"]!!).readBytes()
                        val result = chain.fetchPoint(input)
                        assertArrayEquals(
                            expectedBytes,
                            result.toByteArray(Charsets.UTF_8),
                            "$caseName fetch_point ($input)",
                        )
                        val resolved = parsePointAddress(input)?.let { chain.resolvePoint(it) } != null
                        assertEquals(
                            kv["resolved"]!!.toBoolean(),
                            resolved,
                            "$caseName fetch_point ($input) resolved flag",
                        )
                    }
                    "fetch_range" -> {
                        val expectedBytes = File(caseDir, kv["file"]!!).readBytes()
                        val result = chain.fetchRange(input)
                        assertArrayEquals(
                            expectedBytes,
                            result.toByteArray(Charsets.UTF_8),
                            "$caseName fetch_range ($input)",
                        )
                        val resolved = parseRangeAddress(input)?.let { chain.resolveRange(it) } != null
                        assertEquals(
                            kv["resolved"]!!.toBoolean(),
                            resolved,
                            "$caseName fetch_range ($input) resolved flag",
                        )
                    }
                    else -> throw AssertionError("$caseName: unknown op kind $kind")
                }
                caseOps += 1
                totalOps += 1
            }
            assertEquals(header["ops"]!!.toInt(), caseOps, "$caseName op count")
            println("range fixture case $caseName: PASS ($caseOps ops)")
        }
        assertEquals(69, totalOps, "expected 69 ops across all range fixture cases")
    }
}
